import { PAGERDUTY_INCIDENT_EVENT_TYPES } from "../../internal/continuation-identity.js";
/** {@link ChannelMeta.kind} value used by {@link pagerdutyChannel}. */
export const PAGERDUTY_CHANNEL_KIND = "pagerduty";
/** Every v3 `event_type` that names one incident; the selector's membership. */
export { PAGERDUTY_INCIDENT_EVENT_TYPES };
/** Lifecycle events whose `data` is the full incident; `onIncident` receives them. */
export const PAGERDUTY_INCIDENT_LIFECYCLE_EVENTS = [
    "incident.triggered",
    "incident.acknowledged",
    "incident.unacknowledged",
    "incident.escalated",
    "incident.reassigned",
    "incident.delegated",
    "incident.resolved",
    "incident.reopened",
    "incident.priority_updated",
    "incident.incident_type.changed",
];
/** `incident.annotated`: a note on the incident; `onNote` receives it. */
export const PAGERDUTY_NOTE_EVENTS = ["incident.annotated"];
/** Responder requests and replies; `onResponder` receives them. */
export const PAGERDUTY_RESPONDER_EVENTS = [
    "incident.responder.added",
    "incident.responder.replied",
];
/**
 * The event types the channel publishes as `meta.pagerdutyWebhookEvents`
 * and the deploy manifest's `eventTypes`: a pinned list, or every incident
 * event. Every typed hook and the default dispatch fall inside that set, so
 * an omitted selector defaults to `pagerduty.incident/v2`.
 */
export function derivePagerDutyWebhookEvents(options) {
    const events = options.webhookEvents ?? PAGERDUTY_INCIDENT_EVENT_TYPES;
    return [...new Set(events.map((event) => event.trim()).filter(Boolean))];
}
export function isPagerDutyIncidentLifecycleEvent(eventType) {
    return PAGERDUTY_INCIDENT_LIFECYCLE_EVENTS.includes(eventType);
}
